/*
 * Fault-injection preload used ONLY by this patch-port validation.
 *
 * Simulates the time-of-check/time-of-use condition in
 * copy_or_link_directory(): the directory iterator's lstat() sees the
 * object entry as its (regular-file) target, so the S_ISLNK() guard does
 * not fire, while the filesystem entry is actually a symlink.  The
 * subsequent realpath()/link() calls observe the real symlink.
 *
 * Only call #1 for the exact path named by HIDE_SYMLINK is faked; later
 * calls (e.g. inside strbuf_realpath()) see the real symlink.
 */

typedef int (*lstat64_fn)(const char *, struct stat64 *);
static lstat64_fn real_lstat64;
static int match_count;

int lstat64(const char *path, struct stat64 *buf)
{
	const char *hide;
	if (!real_lstat64)
		real_lstat64 = (lstat64_fn)dlsym(RTLD_NEXT, "lstat64");
	hide = getenv("HIDE_SYMLINK");
	if (hide && path && !strcmp(path, hide)) {
		match_count++;
		if (getenv("HIDE_DEBUG"))
			fprintf(stderr, "[libhide] lstat64(%s) call #%d\n",
				path, match_count);
		if (match_count == 1) {
			int r = stat64(path, buf);
			if (getenv("HIDE_DEBUG"))
				fprintf(stderr, "[libhide]   -> stat64 mode=%o r=%d\n",
					(unsigned)buf->st_mode, r);
			return r;
		}
	}
	return real_lstat64(path, buf);
}

